          ]
        },
        {
          "proposicao": "A análise proposta pela fonte considera que problemas operacionais em plantas de separação podem resultar em perdas de produção e/ou menor qualidade dos fluidos produzidos.",
          "trechos": [
            "Ed6e2bd82024825f8:700:1393"
          ],
